          ${FormField({
            id: "fullName",
            label: "Full name",
            type: "text",
            placeholder: "Taylor Morgan",
            required: true,
            value: state.values.fullName,
            error: displayError("fullName")
          })}
          ${FormField({
            id: "email",
            label: "Email address",
            type: "email",
            placeholder: "taylor@example.com",
            required: true,
            value: state.values.email,
            error: displayError("email")
          })}
