          />
          ${helperText ? `<p class="helper-text" id="${id}-help">${helperText}</p>` : ""}
          <p class="error-text" id="${id}-error">${error || ""}</p>
        </div>
      `;
    }

    function ContactForm(errors) {
      const displayError = (field) =>
        (state.submitted || state.touched[field]) ? errors[field] || "" : "";

      return `
        <form id="support-form" novalidate>
          ${FormField({
            id: "fullName",
            label: "Full name",
            type: "text",
            placeholder: "Taylor Morgan",
            required: true,
            value: state.values.fullName,
            error: displayError("fullName")
          })}
          ${FormField({
            id: "email",
            label: "Email address",
            type: "email",
            placeholder: "taylor@example.com",
            required: true,
            value: state.values.email,
            error: displayError("email")
          })}
          ${FormField({
            id: "phone",
            label: "Phone number",
            type: "tel",
            placeholder: "(555) 123-4567",
            required: false,
            helperText: "Optional. Use a format like (555) 123-4567 or +1 555-123-4567.",
            value: state.values.phone,
            error: displayError("phone")
          })}
          <div class="submit-row">
            <p class="form-status" aria-live="polite">${state.status}</p>
            <button type="submit">Submit</button>
          </div>
        </form>
      `;
    }

    function SupportPage() {
      const errors = validate(state.values);

      return `
        <main class="support-shell">
          <header class="support-header">
            <p class="eyebrow">Support</p>
            <h1>Contact our team</h1>
            <p class="support-copy">
              Share a few details and a support specialist will follow up with the right next step.
            </p>
          </header>
          <section class="form-content">
            ${ContactForm(errors)}
          </section>
        </main>
      `;
    }

    function App() {
      return SupportPage();
    }

    function escapeHtml(value) {
      return value
